import * as React from "react"
import { ArrowRight } from "lucide-react"
import { cn } from "@/lib/utils"
import { AspectImage } from "@/components/lazer/aspect-image"

/**
 * Feature Row · Layout=Three cards · Lazer DS Starter Kit
 * Figma: Landing Page Modules, Feature Row set. Columns wrap at a 280 floor:
 * three across on Desktop, two then one on Tablet, stacked on Mobile.
 * Band padding follows 04 Responsive (grid/margin, space/section-padding-block).
 */
export interface FeatureItem {
  title: string
  body: string
  href?: string
  linkLabel?: string
  image?: string
  imageAlt?: string
}

export interface FeatureRowProps extends React.HTMLAttributes<HTMLElement> {
  items: FeatureItem[]
}

export function FeatureRow({ items, className, ...props }: FeatureRowProps) {
  return (
    <section
      data-slot="feature-row"
      className={cn(
        "w-full bg-[var(--surface-page)] px-[var(--grid-margin)] py-[var(--space-section-padding-block)]",
        className
      )}
      {...props}
    >
      <div className="mx-auto grid max-w-[var(--layout-content-max)] grid-cols-[repeat(auto-fit,minmax(280px,1fr))] gap-x-[var(--inline-3xl)] gap-y-[var(--stack-4xl)]">
        {items.map((item) => (
          <article key={item.title} className="flex flex-col gap-[var(--stack-lg)]">
            <AspectImage ratio="3:2" src={item.image} alt={item.imageAlt} />
            <h3 className="lz-h4 text-[var(--text-default)]">{item.title}</h3>
            <p className="lz-body text-[var(--text-muted)]">{item.body}</p>
            {item.href ? (
              <a
                href={item.href}
                className="lz-body-emphasis inline-flex w-fit items-center gap-[var(--inline-xs)] text-[var(--component-link-label)] underline decoration-[var(--component-link-underline)] underline-offset-4 hover:text-[var(--component-link-label-hover)]"
              >
                {item.linkLabel ?? "Learn more"}
                <ArrowRight aria-hidden className="size-[var(--component-icon-size-sm)]" />
              </a>
            ) : null}
          </article>
        ))}
      </div>
    </section>
  )
}
